      {"q": "Quin és el gènere de la sigla PIB?", "o": ["masculí: el PIB, com «producte»", "femení: la PIB", "neutre: no porta article"], "e": "El gènere d'una sigla és el de la primera paraula que representa: el producte interior brut, el PIB."},
      {"q": "Quina afirmació sobre IVAJ (Institut Valencià de la Joventut) és correcta?", "o": ["És un acrònim i es pot escriure IVAJ o Ivaj", "És una sigla i només es pot escriure IVAJ", "S'ha d'escriure I.V.A.J."], "e": "Els acrònims, formats amb grups de lletres, poden anar tot en majúscules o només amb la inicial majúscula."},
      {"q": "Per què «Benelux» és un acrònim i no una sigla pròpiament dita?", "o": ["Perquè està format per grups de lletres de diverses paraules (Belgique, Nederland, Luxembourg)", "Perquè es llig lletra a lletra", "Perquè porta punts entre les lletres"], "e": "La sigla pròpiament dita es forma amb les inicials; l'acrònim, amb grups de lletres que la fan més llegible."},
      {"q": "Com es llig la sigla UGT?", "o": ["Lletra a lletra: [uʤeté]", "Com una paraula: [ugt]", "Desplegada sempre: Unió General de Treballadors"], "e": "UGT és una sigla consonàntica (es lletreja); UNESCO, en canvi, és sil·làbica (es llig com una paraula)."},
      {"q": "Quina forma és correcta?", "o": ["Ha detectat un ovni.", "Ha detectat un OVNI's.", "Ha detectat un O.V.N.I."], "e": "Algunes sigles s'han lexicalitzat i s'escriuen en minúscula, com qualsevol paraula: ovni, sida, làser."},
      {"q": "Què diu la norma sobre sigles com JJOO o CCOO, que dupliquen lletres per a indicar plural?", "o": ["Que és un procediment poc recomanable", "Que és l'única manera correcta de fer el plural", "Que s'han d'escriure amb punts: J.J.O.O."], "e": "Encara que algunes estan consolidades per l'ús, la duplicació de lletres és un procediment poc recomanable."},
      {"q": "Escriu l'abreviatura de «telèfon».", "a": ["tel."], "e": "Tel., per truncament, en minúscula i amb punt."},
      {"q": "Escriu l'abreviatura de «doctora».", "a": ["Dra."], "e": "Dra.: tractament, amb majúscula i punt."},
      {"q": "Escriu l'abreviatura de «carrer» que acaba amb barra.", "a": ["c/"], "e": "Algunes abreviatures acaben amb barra en lloc de punt: c/ (carrer), t/ (taló)."},
      {"q": "Escriu el símbol de «quilòmetres per hora».", "a": ["km/h"], "e": "Km/h: símbol amb barra, sense punt i invariable."},
      {"q": "Escriu el símbol de l'hectàrea.", "a": ["ha"], "e": "Ha, en minúscula i sense punt."},
      {"q": "Escriu la sigla de «producte interior brut».", "a": ["PIB"], "e": "PIB: majúscules, sense punts."},
      {"q": "Escriu amb xifra l'abreviatura de l'ordinal «quarta».", "a": ["4a", "4a.", "4.a"], "e": "Els ordinals s'abreugen amb la xifra i l'última lletra, amb punt o sense: 4a o 4a."},
      {"q": "Escriu l'abreviatura de «senyors».", "a": ["Srs."], "e": "Srs.: l'abreviatura per contracció afig la marca de plural."},
      {"q": "Escriu correctament el topònim: «vila-real».", "a": ["Vila-real"], "e": "En els compostos aglutinats només va en majúscula la primera lletra del primer element: Vila-real, Sud-àfrica."}
    ]
  },
  {
    "id": "6eade6fa-94e2-5861-a020-319ca6f163b6", "type": "c1_fon_puntuacio", "sort_order": 13,
    "title": "Signes de puntuació", "name": "Regles d'ús de tots els signes: pausa, entonació, incisos, claudàtors, asterisc i barra",
    "content": "Regles d'ús de tots els signes de puntuació: coma, punt i coma, punt, dos punts i punts suspensius; signes d'interrogació i d'exclamació; guions, parèntesis, claudàtors i cometes; i altres signes com l'asterisc, la barra o el signe de secció, amb la seua posició i les combinacions entre ells (3.2.1).", "icon": "✒️", "color": "#DCEDC8",
    "exercises": [
      {"q": "En quina frase és correcta la coma davant de «i»?", "o": ["Va actuar sense pensar-s'ho, i probablement eixe va ser el seu error.", "Hem comprat pomes, peres, i taronges.", "Ma mare, i mon pare han vingut a vore'm."], "e": "Es posa coma davant de i quan introduïx un contingut diferent (una conclusió, un matís) respecte a l'anterior; no en una enumeració simple."},
      {"q": "Quina frase està ben puntuada?", "o": ["La creació de plataformes, aplicacions informàtiques, etc., és el nostre objectiu.", "La creació de plataformes, aplicacions informàtiques, etc. és el nostre objectiu.", "La creació de plataformes, aplicacions informàtiques etc., és el nostre objectiu."], "e": "Quan el subjecte és una enumeració tancada amb etc., cal acotar-la entre comes: ..., etc., és."},
      {"q": "Quina frase està ben puntuada?", "o": ["No en vull saber res, de les seues històries.", "No en vull saber res de, les seues històries.", "No en vull, saber res de les seues històries."], "e": "La coma marca l'element desplaçat (dislocat) al final de l'oració, que el pronom en ja anticipa."},
      {"q": "Quina frase està ben puntuada?", "o": ["Conclòs el tràmit d'audiència, l'instructor ha de trametre l'expedient.", "Conclòs el tràmit d'audiència l'instructor, ha de trametre l'expedient.", "Conclòs, el tràmit d'audiència l'instructor ha de trametre l'expedient."], "e": "Les clàusules absolutes de participi o de gerundi se separen amb coma de la resta de l'oració."},
      {"q": "Quina és la forma correcta del títol d'una disposició legal?", "o": ["Llei 28/2005, de 26 de desembre, de mesures sanitàries enfront del tabaquisme", "Llei 28/2005 de 26 de desembre de mesures sanitàries enfront del tabaquisme", "Llei 28/2005: de 26 de desembre; de mesures sanitàries enfront del tabaquisme"], "e": "En els textos legals, la data de promulgació va entre comes."},
      {"q": "Quina datació és correcta al final d'una carta?", "o": ["Almassora, 21 de juny del 2007", "Almassora, 21 de juny del 2007.", "Almassora 21 de juny del 2007."], "e": "El lloc se separa de la data amb coma, i darrere de les datacions no es posa punt."},
      {"q": "Quina adreça està ben puntuada?", "o": ["C/ Pintor Maella, 5", "C/ Pintor Maella 5.", "C/ Pintor Maella: 5"], "e": "En les adreces, una coma separa el nom del carrer del número."},
      {"q": "Quina frase té una coma incorrecta?", "o": ["El president va manifestar, que no acudiria a la reunió.", "El president, molt enfadat, va abandonar la reunió.", "Si no ve el president, ajornarem la reunió."], "e": "No s'ha de posar coma entre el verb i els seus complements, encara que siguen oracions: va manifestar que..."},
      {"q": "En una enumeració complexa separada amb punt i coma, quin signe va davant de l'últim element si l'introduïx la conjunció «i»?", "o": ["una coma", "un punt i coma", "dos punts"], "e": "Hi assistiren la directora, Sra. Melià; el secretari, Sr. Martí, i el vocal, Sr. Grau: davant del darrer element amb i, coma."},
      {"q": "Quina frase està ben puntuada?", "o": ["Vaig poder anar al viatge; amb tot, millor m'haguera quedat en casa.", "Vaig poder anar al viatge, amb tot millor m'haguera quedat en casa.", "Vaig poder anar al viatge amb tot; millor m'haguera quedat en casa."], "e": "Davant de connectors com tanmateix, amb tot o no obstant això en oracions llargues, es posa punt i coma, i coma darrere."},
      {"q": "Quina forma és correcta?", "o": ["l'any 2007", "l'any 2.007", "l'any 2,007"], "e": "No es posa punt de miler en els anys, les pàgines, els codis postals ni els números d'una sèrie ordenada."},
      {"q": "Quina forma és correcta per a una quantitat de diners?", "o": ["72.000 euros", "72,000 euros", "72'000 euros"], "e": "Els milers d'una quantitat se separen amb punt o amb un espai (72 000 €); la coma separa els decimals."},
      {"q": "Segons les normes internacionals, quina forma és preferible per a expressar l'hora?", "o": ["16:45 hores", "16,45 hores", "16'45 hores"], "e": "Per a separar hores i minuts també s'admet el punt (16.45), però és preferible usar els dos punts."},
      {"q": "Quina frase usa els dos punts per a introduir una conseqüència?", "o": ["Té un examen dilluns: no podrà vindre a l'excursió.", "Té un examen: dilluns, i no podrà vindre a l'excursió.", "Té: un examen dilluns i no podrà vindre a l'excursió."], "e": "Els dos punts poden introduir una causa, una conseqüència o una conclusió respecte de l'oració anterior."},
      {"q": "Quina frase està ben puntuada?", "o": ["En la reunió hi havia representants de Belarús, Estònia i Lituània.", "En la reunió hi havia representants de: Belarús, Estònia i Lituània.", "En la reunió hi havia representants: de Belarús, Estònia i Lituània."], "e": "És incorrecte posar dos punts entre una preposició i el substantiu que introduïx."},
      {"q": "Quins signes poden separar la salutació d'una carta del cos del text?", "o": ["Els dos punts o la coma", "Només el punt", "El punt i coma"], "e": "Benvolgut amic: / Marta, — totes dos formes són vàlides."},
      {"q": "Quina combinació de signes és correcta?", "o": ["Lladres, roders, assassins..., eixa és la gent que hi trobaràs.", "Lladres, roders, assassins.... Eixa és la gent que hi trobaràs.", "Lladres, roders, assassins,... eixa és la gent que hi trobaràs."], "e": "Els punts suspensius poden anar seguits de qualsevol signe (coma, punt i coma...) excepte el punt."},
      {"q": "Quina frase està ben puntuada?", "o": ["Tenim el transport, la banca, el comerç, etc.", "Tenim el transport, la banca, el comerç, etc...", "Tenim el transport, la banca, el comerç, etc...."], "e": "No es posen punts suspensius darrere de etc., que ja indica que l'enumeració continua."},
      {"q": "Sobre el signe d'interrogació d'obertura (¿), quina afirmació és correcta segons l'AVL?", "o": ["És opcional, i convé sobretot quan hi pot haver ambigüitat o en textos per a ser llegits en veu alta", "És obligatori en tota pregunta", "No es pot usar mai en valencià"], "e": "Els signes d'interrogació i d'exclamació es poden posar només al final o també al principi, especialment en enunciats llargs o ambigus."},
      {"q": "Quina frase està ben puntuada?", "o": ["Jo només vull saber tres coses: on?, des de quan? i per què?", "Jo només vull saber tres coses: on?. des de quan?. i per què?.", "Jo només vull saber tres coses: on? des de quan? i per què?."], "e": "El signe d'interrogació pot anar seguit de coma, punt i coma o dos punts, però mai de punt."},
      {"q": "Quina frase està ben puntuada?", "o": ["Oh Senyor!, sigueu bondadós amb el vostre poble.", "Oh Senyor!. Sigueu bondadós amb el vostre poble.", "Oh Senyor!, Sigueu bondadós amb el vostre poble."], "e": "El signe d'exclamació pot anar seguit de coma, i aleshores la paraula següent va en minúscula."},
      {"q": "Quina frase està ben puntuada?", "o": ["¿Pot justificar-se en algun cas la violència —es preguntà el conferenciant—?", "¿Pot justificar-se en algun cas la violència— es preguntà el conferenciant?", "¿Pot justificar-se en algun cas la violència —es preguntà el conferenciant?—"], "e": "Si l'incís està dins de la pregunta, el signe d'interrogació de tancament va darrere del guió de tancament."},
      {"q": "Quan el guió de tancament d'un incís coincidix amb el punt final de la frase...", "o": ["pot ometre's", "s'ha d'escriure darrere del punt", "s'ha de substituir per una coma"], "e": "Me'n vaig anar —i no cal que t'explique de quin humor— o bé ...de quin humor. (sense el guió de tancament)."},
      {"q": "Per a què servixen els parèntesis en «Cada persona té el(s) seu(s) ritme(s) d'aprenentatge»?", "o": ["Per a oferir diverses opcions de lectura", "Per a marcar una acotació teatral", "Per a indicar una omissió en una cita"], "e": "Un dels usos dels parèntesis és introduir opcions de lectura en un mateix text."},
      {"q": "Quina frase està ben puntuada?", "o": ["Esta qüestió va ser tractada en el Ple de novembre (celebrat el dia 7); però va ser aprovada en el de desembre.", "Esta qüestió va ser tractada en el Ple de novembre (celebrat el dia 7;) però va ser aprovada en el de desembre.", "Esta qüestió va ser tractada en el Ple de novembre; (celebrat el dia 7) però va ser aprovada en el de desembre."], "e": "La coma, el punt i coma o els dos punts que coincidixen amb un parèntesi de tancament van immediatament després del parèntesi."},
      {"q": "Quin signe s'usa per a posar entre parèntesis un text que ja conté un parèntesi?", "o": ["els claudàtors [ ]", "les cometes « »", "els guions — —"], "e": "Els claudàtors substituïxen els parèntesis quan l'aclariment ja és dins d'un altre parèntesi."},
      {"q": "Per a què servixen els claudàtors en «Nosaltres [els valencians] som mediterranis»?", "o": ["Per a introduir un aclariment de qui cita dins d'una citació", "Per a indicar que el text és agramatical", "Per a marcar una transcripció fonètica"], "e": "Els claudàtors introduïxen aclariments, especialment quan una cita queda incompleta fora del seu context."},
      {"q": "Com s'indica el títol d'un capítol d'un llibre o d'un article de premsa?", "o": ["Entre cometes", "En cursiva", "En majúscules"], "e": "Els títols de capítols, articles, conferències i ponències van entre cometes; els de llibres i publicacions, en cursiva."},
      {"q": "Quina frase usa bé les cometes simples?", "o": ["La paraula otitis prové del grec οὖς ‘orella’.", "La paraula ‘otitis’ prové del grec οὖς «orella».", "La paraula otitis prové del grec οὖς “orella”."], "e": "Les cometes simples emmarquen el significat d'una paraula."},
      {"q": "En una llista de correccions, per a què s'usen les cometes de tancament (») sota una dada?", "o": ["Per a repetir la dada escrita en la línia anterior", "Per a indicar una cita", "Per a marcar una paraula estrangera"], "e": "Les cometes de tancament suplixen una dada ja escrita en la mateixa posició de la línia anterior."},
      {"q": "Què indica l'asterisc en «La forma *senyalètica és un calc; en valencià es diu senyalística»?", "o": ["Que la forma és incorrecta o agramatical", "Que hi ha una nota a peu de pàgina", "Que la paraula és estrangera"], "e": "En obres lingüístiques, l'asterisc davant d'una forma indica que és agramatical. Darrere d'una paraula, en canvi, crida una nota."},
      {"q": "Per a què s'usa la barra en «Vora el barranc dels Algadins / hi ha uns tarongers de tan dolç flaire»?", "o": ["Per a indicar cada canvi de vers en escriure versos en línia", "Per a indicar oposició entre dos paraules", "Per a separar opcions de lectura"], "e": "Quan els versos s'escriuen seguits, la barra marca el canvi de vers."},
      {"q": "Quina forma és correcta en la referència d'una llei?", "o": ["Llei 4/1988, d'hisenda pública valenciana", "Llei 4-1988, d'hisenda pública valenciana", "Llei 4.1988, d'hisenda pública valenciana"], "e": "La barra separa el número d'orde de l'any de promulgació en els textos normatius."},
      {"q": "Quina frase té els signes dobles ben espaiats?", "o": ["Eduard Escalante (València, 1854-1921) va escriure sainets.", "Eduard Escalante ( València, 1854-1921 ) va escriure sainets.", "Eduard Escalante(València, 1854-1921)va escriure sainets."], "e": "El signe d'obertura va separat de la paraula anterior i unit a la següent; el de tancament, unit a l'anterior i separat de la següent."},
      {"q": "Quina frase està ben puntuada?", "o": ["Els assistents el van ovacionar quan va dir que «la guerra és sempre una derrota».", "Els assistents el van ovacionar quan va dir que «la guerra és sempre una derrota.»", "Els assistents el van ovacionar quan va dir que «la guerra és sempre una derrota.»."], "e": "Si les cometes s'obrin dins de la frase, el punt va darrere de les cometes de tancament."},
      {"q": "Com s'anomena el signe [ ]?", "a": ["claudàtors", "claudàtor", "els claudàtors"], "e": "Els claudàtors són un signe doble d'obertura i tancament."},
