      {"q": "Escriu el signe que separa el número d'orde i l'any en «Llei 4___1988».", "a": ["/", "barra", "barra inclinada"], "e": "La barra inclinada: Llei 4/1988."},
      {"q": "Escriu el signe que es posa entre claudàtors per a indicar que s'ha suprimit una part d'una cita.", "a": ["...", "…", "punts suspensius", "[...]", "[…]"], "e": "Els punts suspensius entre claudàtors, [...], indiquen una omissió dins d'una citació textual."},
      {"q": "Com s'anomenen les cometes ‘ ’?", "a": ["simples", "cometes simples"], "e": "Les cometes simples s'usen per al significat d'una paraula i dins de cometes altes."},
      {"q": "Com s'anomenen les cometes “ ”?", "a": ["altes", "angleses", "cometes altes", "cometes angleses"], "e": "Les cometes altes o angleses s'usen dins de les baixes (« »)."},
      {"q": "Escriu sense errors l'any «2.024».", "a": ["2024"], "e": "En els anys no es posa punt de miler."},
      {"q": "Escriu el signe de puntuació que pot substituir la coma darrere de «Benvolguda directora» en l'encapçalament d'una carta (escriu-ne el nom).", "a": ["dos punts", "els dos punts", ":"], "e": "Benvolguda directora: o Benvolguda directora, — les dos opcions són correctes."},
      {"q": "Com s'anomena el signe § que remet a una divisió interna d'un llibre?", "a": ["signe de secció", "secció", "el signe de secció"], "e": "El signe de secció (§), seguit d'un número, remet a un apartat: § 15.5.1."},
      {"q": "Escriu correctament: «Quan vindràs?.»", "a": ["Quan vindràs?"], "e": "Darrere del signe d'interrogació o d'exclamació no es posa mai punt."}
    ]
  }
]$data$::jsonb) AS t(
  id uuid, type text, sort_order smallint, title text, name text,
  content text, icon text, color text, exercises jsonb
);

INSERT INTO public.resources (id, name, type, category, content, difficulty, xp_earned, sort_order, metadata)
SELECT id, name, type, 'fonetica_ortografia', content, 'C1', 15, sort_order,
       jsonb_build_object('icon', icon, 'color', color, 'section_name', title)
FROM practice_catalog
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  type = EXCLUDED.type,
  category = EXCLUDED.category,
  content = EXCLUDED.content,
  difficulty = EXCLUDED.difficulty,
  xp_earned = EXCLUDED.xp_earned,
  sort_order = EXCLUDED.sort_order,
  -- Conserva la lliçó fixa («Aprendre lliçó»), si una migració posterior n'hi afig.
  metadata = EXCLUDED.metadata || jsonb_strip_nulls(jsonb_build_object('lesson', resources.metadata -> 'lesson'));

DELETE FROM public.practice_exercises e
USING practice_catalog c
WHERE e.resource_id = c.id AND e.level = 'C1';

INSERT INTO public.practice_exercises (resource_id, level, position, kind, prompt, options, answers, explanation)
SELECT c.id, 'C1', x.ord,
       CASE WHEN x.e ? 'a' THEN 'fill' ELSE 'choice' END,
       x.e->>'q',
       CASE WHEN x.e ? 'o' THEN ARRAY(SELECT jsonb_array_elements_text(x.e->'o')) END,
       CASE WHEN x.e ? 'a' THEN ARRAY(SELECT jsonb_array_elements_text(x.e->'a')) ELSE ARRAY[x.e->'o'->>0] END,
       x.e->>'e'
FROM practice_catalog c
CROSS JOIN LATERAL jsonb_array_elements(c.exercises) WITH ORDINALITY AS x(e, ord);

DROP TABLE practice_catalog;
